using System;using System.Collections.Generic;using System.Linq;using Echo.Interactions;using Echo.Radio;using Echo.Audio;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Object=UnityEngine.Object;using static Echo.Manor.Editor.ManorSetDress;
namespace Echo.Manor.Editor {
 public static class ManorFirstRoomsIntegrity {
  public const string Marker="First rooms physical integrity P0";
  public const string Folder="Assets/Props/FirstRoomsIntegrity";
  private static readonly Dictionary<Mesh,Mesh> collisionCache=new Dictionary<Mesh,Mesh>();
  private static Transform root;private static Material wood,iron,glass;
  [MenuItem("Echo/Узгодити фізику перших двох кімнат")]
  public static void ApplyAndSave(){if(EditorSceneManager.GetActiveScene().path!=ManorPrototypeBuilder.ScenePath)throw new InvalidOperationException("Open ManorPrototype first");collisionCache.Clear();Apply();RefineFurniture();EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();}
  public static void Apply(){if(GameObject.Find(Marker)!=null)return;System.IO.Directory.CreateDirectory(Folder);AssetDatabase.Refresh();root=Group(Marker);wood=Load("Aged timber");iron=Load("Dark iron");glass=Load("Moonlit broken glass");CorrectDoor("Service Door","Human-scale service door visual");CorrectDoor("Hall Code Door","Human-scale hall door visual");MountLock();AlignCupboard();RefineFurniture();GroundDecorations();OpenWindows();ConfigureRecording();Debug.Log("P0_FIRST_ROOMS_APPLIED");}
  private static Material Load(string name)=>AssetDatabase.LoadAssetAtPath<Material>(MaterialsFolder+"/"+name+".mat");
  private static Bounds Visible(Transform go){bool first=true;var bounds=new Bounds();foreach(var f in go.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<Renderer>();if(f.sharedMesh==null||r==null||!r.enabled)continue;var b=f.sharedMesh.bounds;for(int i=0;i<8;i++){var p=f.transform.TransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1)));if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}}return bounds;}
  private static GameObject Part(string name,Transform owner,Vector3 local,Vector3 size,Material material,bool solid=true){var go=Box(name,null,Vector3.zero,size,material,solid);go.transform.SetParent(owner,false);go.transform.localPosition=local;return go;}
  private static void CorrectDoor(string name,string visualName){var door=GameObject.Find(name).GetComponent<HingedDoor>();var visual=door.GetComponentsInChildren<Transform>().First(t=>t.name==visualName);var centre=Visible(visual).center;visual.RotateAround(centre,Vector3.up,180);visual.position+=centre-Visible(visual).center;door.hinge.position-=door.hinge.forward*.13f;door.openAngle=90;foreach(float y in new[]{.40f,2.03f}){Part("Visible jamb hinge",door.hinge,new Vector3(-.015f,y,0),new Vector3(.04f,.13f,.09f),iron,false);}}
  private static void MountLock(){var door=GameObject.Find("Hall Code Door").GetComponent<HingedDoor>();var keypad=GameObject.Find("Three Digit Lock").GetComponent<KeypadLock>();var view=keypad.physicalView;if(view==null){foreach(var r in keypad.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var c in keypad.GetComponentsInChildren<Collider>(true))c.enabled=false;keypad.transform.localScale=Vector3.one;var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Props/ManorInteractive/PF_ManorCombinationLock.prefab");if(prefab==null)throw new InvalidOperationException("Physical lock prefab missing");var visual=(GameObject)PrefabUtility.InstantiatePrefab(prefab);visual.name="Physical Lock Visual";visual.transform.SetParent(keypad.transform,false);Object.DestroyImmediate(visual.GetComponent<KeypadLock>());view=visual.GetComponent<MechanicalLockView>();view.keypad=keypad;keypad.physicalView=view;}var collision=view.GetComponentsInChildren<Collider>().First(c=>c.enabled&&c.name=="Collision");var bounds=collision.bounds;float back=float.PositiveInfinity;for(int i=0;i<8;i++){var p=bounds.center+Vector3.Scale(bounds.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));back=Mathf.Min(back,keypad.transform.InverseTransformPoint(p).z);}var surface=door.hinge.TransformPoint(new Vector3(1.3f*.78f,1.47f,-.065f));var normal=-door.hinge.forward;keypad.transform.SetParent(door.hinge,true);keypad.transform.SetPositionAndRotation(surface+normal*(.004f-back),Quaternion.LookRotation(normal,Vector3.up));keypad.transform.localScale=Vector3.one;Part("Lock mounting hasp",door.hinge,new Vector3(1.3f*.78f,1.65f,-.073f),new Vector3(.12f,.08f,.016f),iron,false);}
  private static Bounds[] ShelfTops(Transform cupboard){var f=cupboard.GetComponentsInChildren<MeshFilter>().First(m=>m.name=="CabinetBody");var vertices=f.sharedMesh.vertices;var triangles=f.sharedMesh.triangles;var planes=new Dictionary<int,Bounds>();for(int i=0;i<triangles.Length;i+=3){var a=f.transform.TransformPoint(vertices[triangles[i]]);var b=f.transform.TransformPoint(vertices[triangles[i+1]]);var c=f.transform.TransformPoint(vertices[triangles[i+2]]);var n=Vector3.Cross(b-a,c-a);if(n.normalized.y<.98f||n.magnitude*.5f<.12f)continue;var box=new Bounds(a,Vector3.zero);box.Encapsulate(b);box.Encapsulate(c);int y=Mathf.RoundToInt(a.y*1000);if(planes.TryGetValue(y,out var old)){old.Encapsulate(box);planes[y]=old;}else planes.Add(y,box);}return planes.Values.Where(b=>b.size.x>.7f&&b.size.z>.3f).OrderBy(b=>b.center.y).ToArray();}
  private static void AlignCupboard(){var cupboard=GameObject.Find("Service Cupboard").transform;var shelves=ShelfTops(cupboard);var old=cupboard.GetComponentsInChildren<BoxCollider>().Where(c=>c.name=="Service Cupboard Shelf").OrderBy(c=>c.bounds.center.y).ToArray();for(int i=0;i<shelves.Length;i++){GameObject go=i<old.Length?old[i].gameObject:new GameObject("Service Cupboard Shelf",typeof(BoxCollider));go.transform.SetParent(cupboard,true);go.transform.SetPositionAndRotation(shelves[i].center-Vector3.up*.02f,Quaternion.identity);go.transform.localScale=new Vector3(shelves[i].size.x,.04f,shelves[i].size.z);go.GetComponent<BoxCollider>().size=Vector3.one;}for(int i=shelves.Length;i<old.Length;i++)old[i].enabled=false;Physics.SyncTransforms();var key=GameObject.Find("Service Key");var shelf=shelves.Where(b=>b.center.y<key.transform.position.y+.01f).Last();var bounds=Visible(key.transform);key.transform.position+=new Vector3(0,shelf.center.y+.002f-bounds.min.y,-.10f);var target=key.GetComponent<BoxCollider>();target.size=new Vector3(.18f,.14f,.14f);var leaf=GameObject.Find("Service Cupboard Door").GetComponent<HingedDoor>();leaf.openAngle=90;leaf.hinge.position-=Vector3.forward*.04f;foreach(float y in new[]{.38f,1.80f})Part("Cupboard hinge plate",leaf.hinge,new Vector3(.02f,y,-.075f),new Vector3(.045f,.14f,.02f),iron,false);Part("Cupboard pull",leaf.hinge,new Vector3(1.34f,1.12f,-.09f),new Vector3(.035f,.18f,.04f),iron,false);}
  private static bool InFirstRooms(Vector3 p)=>p.x> -20&&p.x<4&&p.z> -12&&p.z< -4&&p.y<3.6f;
  private static void Ground(Transform item){var bounds=Visible(item);if(bounds.size==Vector3.zero)return;var hits=Physics.RaycastAll(new Vector3(bounds.center.x,bounds.min.y+.06f,bounds.center.z),Vector3.down,.25f,~0,QueryTriggerInteraction.Ignore).Where(h=>!h.collider.transform.IsChildOf(item)&&h.normal.y>.9f).OrderBy(h=>h.distance);if(hits.Any()){var hit=hits.First();item.position+=Vector3.up*(hit.point.y+.002f-bounds.min.y);}}
  private static Mesh ReadableCollision(Mesh source){if(collisionCache.TryGetValue(source,out var cached))return cached;string path=Folder+"/Collision "+source.name+".asset";var mesh=new Mesh{name="Readable collision "+source.name};mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.vertices=source.vertices;mesh.triangles=source.triangles;mesh.RecalculateNormals();mesh.RecalculateBounds();var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null){EditorUtility.CopySerialized(mesh,existing);Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,path);collisionCache[source]=mesh;return mesh;}
  private static void RefineFurniture(){var owner=GameObject.Find("Gallery window console");if(owner!=null){var broad=owner.GetComponentsInChildren<BoxCollider>().FirstOrDefault(c=>c.name=="Console collision");if(broad!=null)broad.enabled=false;foreach(var f in owner.GetComponentsInChildren<MeshFilter>().Where(f=>f.name=="SM_ManorTable")){var collider=f.GetComponent<MeshCollider>();if(collider==null)collider=f.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=ReadableCollision(f.sharedMesh);}}foreach(var t in Object.FindObjectsByType<Transform>().Where(t=>(t.name.StartsWith("Scattered shelf ")||t.name.StartsWith("Shelf decoration - "))&&InFirstRooms(Visible(t).center)).ToArray())foreach(var f in t.GetComponentsInChildren<MeshFilter>()){var collider=f.GetComponent<MeshCollider>();if(collider!=null)collider.sharedMesh=ReadableCollision(f.sharedMesh);}}
  private static void GroundDecorations(){Physics.SyncTransforms();foreach(var t in Object.FindObjectsByType<Transform>().ToArray()){if(!InFirstRooms(Visible(t).center))continue;if(t.name.StartsWith("Scattered shelf ")||t.name.StartsWith("Shelf decoration - ")||(t.name.StartsWith("Model - PF_Decor")&&!t.name.Contains("Portrait"))||t.name=="Scattered blank paper - decoration")Ground(t);}var note=GameObject.Find("Service Card");Ground(note.transform);foreach(var t in Object.FindObjectsByType<Transform>().Where(t=>(t.name.StartsWith("Scattered shelf ")||t.name.StartsWith("Shelf decoration - "))&&InFirstRooms(Visible(t).center)).ToArray())foreach(var f in t.GetComponentsInChildren<MeshFilter>())if(f.sharedMesh!=null&&f.GetComponent<Collider>()==null)f.gameObject.AddComponent<MeshCollider>().sharedMesh=ReadableCollision(f.sharedMesh);Physics.SyncTransforms();}
  private static void SaveMesh(Mesh mesh,string name){AssetDatabase.CreateAsset(mesh,Folder+"/"+name+".asset");}
  private static void OpenWindows(){var holes=Object.FindObjectsByType<GalleryWindowShutter>().Select(w=>new Rect(w.transform.position.x-.85f,1.05f,1.7f,2)).ToArray();foreach(var f in Object.FindObjectsByType<MeshFilter>().Where(f=>f.name.StartsWith("Continuous wall ")).ToArray()){var b=f.GetComponent<Renderer>().bounds;if(b.min.z> -11.89f||b.max.z< -12.11f||b.max.x< -7.7f||b.min.x>2.1f)continue;var cut=WindowWallCut.Cut(f.sharedMesh,f.transform,holes);SaveMesh(cut,f.name+" aperture revision");f.sharedMesh=cut;}
   var wall=Object.FindObjectsByType<BoxCollider>().First(c=>c.name=="Wall S"&&Vector3.Distance(c.bounds.center,new Vector3(-3,2,-12))<.05f);wall.enabled=false;var spans=new List<float>{-10,4};foreach(var h in holes){spans.Add(h.xMin);spans.Add(h.xMax);}spans.Sort();for(int i=0;i<spans.Count-1;i++){float x=(spans[i]+spans[i+1])/2;bool opening=holes.Any(h=>x>h.xMin&&x<h.xMax);foreach(var interval in opening?new[]{new Vector2(0,1.05f),new Vector2(3.05f,4)}:new[]{new Vector2(0,4)}){var block=Box("Gallery aperture wall collision",root,new Vector3(x,(interval.x+interval.y)/2,-12),new Vector3(spans[i+1]-spans[i],interval.y-interval.x,.2f),wood);block.GetComponent<Renderer>().enabled=false;}}
   foreach(var window in Object.FindObjectsByType<GalleryWindowShutter>()){window.GetComponent<BoxCollider>().enabled=false;window.transform.Find("Moonlit window pane").gameObject.SetActive(false);foreach(Transform child in window.transform){if(child.name=="Window mullion"||child.name=="Window crossbar"){var p=child.localPosition;p.z=-.13f;child.localPosition=p;var size=child.localScale;size.z=.38f;child.localScale=size;}if(child.name=="Window mullion"||child.name=="Window crossbar"||child.name=="Window sill")if(child.GetComponent<BoxCollider>()==null)child.gameObject.AddComponent<BoxCollider>();}
    foreach(var hinge in new[]{window.leftHinge,window.rightHinge}){var p=hinge.localPosition;p.z=.10f;hinge.localPosition=p;var board=hinge.GetComponentsInChildren<Transform>().First(t=>t.name=="Shutter boards");if(board.GetComponent<BoxCollider>()==null)board.gameObject.AddComponent<BoxCollider>();}
    BrokenGlass(window);for(int i=0;i<5;i++)Part("Exterior security bar",window.transform,new Vector3(-.64f+i*.32f,0,-.38f),new Vector3(.035f,2.06f,.035f),iron);foreach(float y in new[]{-.99f,.99f}){Part("Grille cross rail",window.transform,new Vector3(0,y,-.38f),new Vector3(1.75f,.035f,.035f),iron);foreach(float x in new[]{-.86f,.86f})Part("Grille wall fixing",window.transform,new Vector3(x,y,-.335f),new Vector3(.055f,.055f,.15f),iron);}
    var audio=window.GetComponent<AmbientCycle>();audio.windClip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/GalleryPrototype/WindowWind.wav");audio.windPlaybackVolume=.24f;
   }
  }
  private static void BrokenGlass(GalleryWindowShutter window){var vertices=new List<Vector3>();var triangles=new List<int>();void Tri(Vector3 a,Vector3 b,Vector3 c){int n=vertices.Count;vertices.AddRange(new[]{a,b,c});triangles.AddRange(new[]{n,n+1,n+2});}foreach(float x in new[]{-.82f,.05f})foreach(float y in new[]{-.97f,.05f}){float w=.77f,h=.92f,z=-.20f;Tri(new Vector3(x,y,z),new Vector3(x+w*.55f,y,z),new Vector3(x+w*.13f,y+h*.42f,z));Tri(new Vector3(x+w,y+h,z),new Vector3(x+w*.55f,y+h,z),new Vector3(x+w*.91f,y+h*.55f,z));}
   var mesh=new Mesh{name="Jagged retained glass"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();SaveMesh(mesh,window.name+" broken panes");var go=new GameObject("Broken window panes",typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));go.transform.SetParent(window.transform,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<Renderer>().sharedMaterial=glass;go.GetComponent<MeshCollider>().sharedMesh=mesh;
   var floor=Group("Fallen glass below "+window.name,root);floor.position=new Vector3(window.transform.position.x,.008f,-11.22f);for(int i=0;i<4;i++){var shard=Part("Glass shard on floor",floor,new Vector3(-.38f+i*.24f,0,(i%2)*.14f),new Vector3(.12f,.006f,.06f),glass,false);shard.transform.localRotation=Quaternion.Euler(0,i*43,0);} }
  private static void ConfigureRecording(){var channel=AssetDatabase.LoadAssetAtPath<RadioChannel>("Assets/RadioData/Gallery940.asset");channel.digitClips=Enumerable.Range(0,10).Select(i=>AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/GalleryPrototype/Digit"+i+".wav")).ToArray();if(channel.digitClips.Any(c=>c==null))throw new InvalidOperationException("Digit audio missing");EditorUtility.SetDirty(channel);}
 }
}
